import java.io.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
/** Standalone public-JDK canonical JSON oracle; never uses the BTA fixture renderer. */
public final class ManifestCanonicalProbe {
 static String str(DataInputStream in)throws IOException {int n=in.readInt();if(n<0||n>1000000)throw new IOException();char[] chars=new char[n];for(int i=0;i<n;i++)chars[i]=in.readChar();return new String(chars);}
 static String quote(String s){StringBuilder b=new StringBuilder("\"");for(int i=0;i<s.length();i++){char c=s.charAt(i);if(Character.isHighSurrogate(c)){if(i+1==s.length()||!Character.isLowSurrogate(s.charAt(i+1)))throw new IllegalArgumentException();b.append(c).append(s.charAt(++i));continue;}if(Character.isLowSurrogate(c))throw new IllegalArgumentException();switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\b':b.append("\\b");break;case '\f':b.append("\\f");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}
 static String read(DataInputStream in,int depth)throws IOException {if(depth>32)throw new IOException();int t=in.readUnsignedByte();switch(t){case 0:return "null";case 1:return "false";case 2:return "true";case 3:{String s=str(in);long n=Long.parseLong(s);if(n<0||n>9007199254740991L||s.equals("-0"))throw new IllegalArgumentException();return Long.toString(n);}case 4:return quote(str(in));case 5:{int n=in.readInt();if(n<0||n>100000)throw new IOException();List<String> a=new ArrayList<>();for(int i=0;i<n;i++)a.add(read(in,depth+1));return "["+String.join(",",a)+"]";}case 6:{int n=in.readInt();if(n<0||n>100000)throw new IOException();TreeMap<String,String> m=new TreeMap<>();for(int i=0;i<n;i++){String k=str(in);quote(k);if(m.put(k,read(in,depth+1))!=null)throw new IOException();}List<String> a=new ArrayList<>();for(var e:m.entrySet())a.add(quote(e.getKey())+":"+e.getValue());return "{"+String.join(",",a)+"}";}default:throw new IOException();}}
 public static void main(String[]args)throws Exception{DataInputStream in=new DataInputStream(System.in);while(in.available()>0){int n=in.readInt();if(n<0||n>1048576)throw new IOException();byte[] bytes=in.readNBytes(n);try{DataInputStream frame=new DataInputStream(new ByteArrayInputStream(bytes));String value=read(frame,0);if(frame.available()!=0)throw new IOException();System.out.println(Base64.getEncoder().encodeToString(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){System.out.println("REJECT");}}}
}
